upper-confidence-bound-for-trees.pseudocode:
def uct_select(node, c=1.414):
    # 승률(활용) + 탐험 항이 최대인 자식
    return max(node.children, key=lambda ch:
               ch.w / ch.n
               + c * sqrt(log(node.n) / ch.n))

def mcts(root, iters):
    for _ in range(iters):
        node = root
        # 1 선택: 완전 확장된 노드는 UCT로 하강
        while node.fully_expanded() and node.children:
            node = uct_select(node)
        if not node.terminal():  # 2 확장
            node = node.expand_one()
        reward = rollout(node.state)  # 3 시뮬레이션
        while node:  # 4 역전파(2인 게임은 부호 교대)
            node.n += 1
            node.w += reward
            node = node.parent
    return max(root.children, key=lambda ch: ch.n)
